css:
.sb-root{position:absolute;left:50%;top:48px;transform:translateX(-50%);display:flex;align-items:stretch;font-family:var(--sb-font);background:rgba(10,10,11,.94);border:1px solid #2e2e2e;border-bottom:2px solid var(--sb-accent);}
.sb-side{display:flex;align-items:center;gap:14px;padding:9px 20px;min-width:250px;}
.sb-left{justify-content:flex-end;}
.sb-right{justify-content:flex-start;}
.sb-logo{position:relative;width:var(--sb-logo);height:var(--sb-logo);flex:0 0 auto;display:flex;align-items:center;justify-content:center;}
.sb-logo img{width:100%;height:100%;object-fit:contain;display:none;}
.sb-logo img.is-ready{display:block;}
.sb-logo-fb{width:6px;height:6px;background:var(--sb-accent);}
.sb-logo:has(img.is-ready) .sb-logo-fb{display:none;}
.sb-team{font-size:var(--sb-team-size);font-weight:700;color:#f2f2f2;letter-spacing:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:240px;}
.sb-team:empty{display:none;}
.sb-score{font-family:ui-monospace,Consolas,monospace;font-size:var(--sb-score-size);font-weight:700;color:#fff;font-variant-numeric:tabular-nums;line-height:1;min-width:1.2em;text-align:center;}
.sb-mid{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;padding:0 18px;border-left:1px solid #2e2e2e;border-right:1px solid #2e2e2e;min-width:72px;}
.sb-label{font-size:11px;font-weight:600;letter-spacing:1.5px;color:#9a9a9a;white-space:nowrap;}
.sb-label:empty{display:none;}
.sb-vs{font-size:11px;font-weight:700;letter-spacing:2px;color:var(--sb-accent);}
